/// Wrapper body for the dual-leg (or single-leg) arbitrage submit.
/// 
/// Mirrors `OKTSCommitArbitrageParams.genParams`.
#[derive(Debug, Clone, PartialEq)]
pub struct ArbitragePlaceOrderInput {
    /// `"true"` / `"false"` — **string**, per `genParams`. When `inst_list` has a
    /// single entry the server requires `"false"`; the interactor enforces that
    /// so the request layer stays a pure transport.
    pub associate: String,
    /// Always `"arbitrage"` for this flow (`- ordType` override on the wrapper).
    pub ord_type: String,
    /// One entry per leg. Both-legs submit sends 2; per-leg submit sends 1 with
    /// `major = "true"` (`OKTASPOContentVC.m:880-883`).
    pub inst_list: Vec<ArbitragePlaceOrderLeg>,
    /// IM attribution tag — opaque passthrough. **Emitted only when present.**
    /// `genParams` guards with `if (self.tag)`, so an organic create must carry
    /// no `tag` key at all; a `"tag":""` would be a wire regression (FR-3).
    pub tag: Option<String>,
}

/// One leg of a manual dual-leg arbitrage order.
/// 
/// Mirrors `OKTSCommitArbitrageItem`. Field order follows the ObjC assignment
/// order in `getCommitArbitrageParams` so a reviewer can read the two side by side.
#[derive(Debug, Clone, PartialEq)]
pub struct ArbitragePlaceOrderLeg {
    /// `params.instId = self.instContext.instrument.instId`
    pub inst_id: String,
    /// `params.tdMode = self.cangMode` — trade mode slug (`cross` / `isolated` / `cash`).
    pub td_mode: String,
    /// `params.side = self.sideFromCurrentDirValue` (`buy` / `sell`).
    pub side: String,
    /// `params.posSide = [OKTPOCommonUtil posSideWithDirectionValue:side:]`.
    pub pos_side: String,
    /// `params.reduceOnly` — **string** `"true"` / `"false"`, per `genParams`.
    pub reduce_only: String,
    /// `params.major = (self.legType == OKTASPOLegTypeLeft)` — **string**
    /// `"true"` / `"false"`. Exactly one leg is major.
    pub major: String,
    /// `params.pxType = self.priceGridVC.arbPriceType` — one of `enter`,
    /// `marketPrice`, `counterpartyPrice`, `overpriced`, `queuingPrice`.
    pub px_type: String,
    /// `params.enterPx` — assigned **only** when `pxType == "enter"`
    /// (`OKTASPOContentVC.m:897-899`). `None` elsewhere so the key is absent,
    /// never `""`.
    pub enter_px: Option<String>,
    /// `params.sz = [self.quantityVC quantityValueWithSide:side]`.
    pub sz: String,
    /// `params.ccy = self.marginedCCYValue` — nullable in the ObjC model, so
    /// absent rather than `""` when unset.
    pub ccy: Option<String>,
    /// `params._last = self.instContext.ticker.last`. Wire key keeps the leading
    /// underscore — see the module doc.
    pub last: String,
    /// `isTradeBorrowMode` — **not** one of the content VC's assignments. It is the
    /// `OKTOrderParams` base-class `BOOL` (`OKTOrderParams.h:107`), which
    /// `paramsFromSelf` reflection emits whether or not anyone assigned it, because
    /// a primitive has no "unset" state. Hence its position: last, outside the
    /// assignment-ordered block above.
    /// 
    /// ⚠️ **A JSON boolean, not a string** — deliberately against this struct's own
    /// convention. `reduceOnly` / `major` / `associate` are strings *only* because
    /// `genParams` explicitly stringifies them (`OKTSCommitArbitrageParams.m:23-24`,
    /// `:38`); this field never passes through that step, so it stays
    /// `NSNumber(BOOL)` and lands on the wire unquoted. `bool_to_wire` must NOT be
    /// applied to it.
    /// 
    /// Always `false` on this page, which is why it is hardcoded at the single
    /// construction site rather than threaded through state: the arbitrage
    /// place-order flow never writes the property (zero assignments under
    /// `placeOrder/arbitrage/`; only TWAP and Smart Iceberg set it, off a borrow
    /// checkbox this page has no counterpart to). Kept as a field anyway so a
    /// future borrow rollout has the seam — but do not wire it to anything without
    /// a native assignment to mirror.
    pub is_trade_borrow_mode: bool,
}

/// Outcome of a multi-order submit.
/// 
/// `algo_id` is empty on rejection; the request layer folds a non-zero `s_code`
/// into `TradingBotError::Network` before this type is constructed, so a
/// successfully-returned value always means the server accepted the order.
#[derive(Debug, Clone, PartialEq)]
pub struct ArbitragePlaceOrderResult {
    pub algo_id: String,
    /// Raw `sCode` as returned. `"0"` on success.
    pub s_code: String,
    /// Server message; may legitimately be empty.
    pub s_msg: Option<String>,
}

/// State for the Arbitrage manual place-order flow.
/// 
/// All price / amount / spread fields cross the FFI boundary as `String`
/// per [`money_math.md`]. Native receives the textual representation;
/// Rust does the math in [`Decimal`].
#[derive(Debug, Clone, PartialEq)]
pub struct ArbitragePlaceOrderState {
    pub left_inst_id: String,
    pub left_px_type: String,
    pub left_enter_px: String,
    pub left_sz: String,
    pub left_side: String,
    pub left_pos_side: String,
    pub left_td_mode: String,
    pub left_ccy: String,
    pub left_reduce_only: bool,
    pub left_is_major: bool,
    pub right_inst_id: String,
    pub right_px_type: String,
    pub right_enter_px: String,
    pub right_sz: String,
    pub right_side: String,
    pub right_pos_side: String,
    pub right_td_mode: String,
    pub right_ccy: String,
    pub right_reduce_only: bool,
    pub right_is_major: bool,
    pub ord_type: String,
    pub associate: bool,
    pub min_amount: String,
    pub min_amount_ccy: String,
    /// FSM tracking the min-amount load lifecycle. `Idle` before
    /// `reload_min_amount`; `Loading` after the action's sync flip;
    /// `Success` on Ok; `Error` on Err. Native reads this for the
    /// loading / error / success transitions.
    pub load_min_amount_state: ActionResultState,
    /// Raw underlying error string from the min-amount fetch — `None`
    /// while idle / loading / on success. Native owns the surrounding
    /// localized copy; Rust holds only the raw error text.
    pub load_min_amount_error: Option<String>,
    pub config_loaded: bool,
    /// FSM for the multi-order submit. `Idle` before any submit; `Loading`
    /// after the action's sync flip; `Success` / `Error` on completion.
    /// Enum-typed, so it carries **no** `#[uniffi(default)]` — a bare
    /// `#[uniffi(default)]` on an enum field compiles under cargo and then
    /// breaks bindgen for both Swift and Kotlin.
    pub submit_state: ActionResultState,
    /// Raw underlying error text from the submit — `None` while idle /
    /// loading / on success. Native owns the surrounding localized copy and
    /// dispatches on the error code it already received via the vended
    /// place-order error handler; Rust holds only the raw text.
    pub submit_error: Option<String>, // default = None
    /// Positive business code (`sCode`) of a rejected submit, as a string —
    /// `None` on success, while idle/loading, and for transport-level failures.
    /// Same shape as `interactors/dca/contract_dca/edit_params.rs:216`.
    /// 
    /// Native's vended place-order error handler DISPATCHES ON THIS
    /// (`OKTPOErrorHandler.m:56-111`): five branches key off `error.code`, and the
    /// generic arm resolves its copy through `[OKTPODataFactory poErrorInfo:error.code]`
    /// before falling back to the message. Reporting the failure as `submit_error`
    /// alone dropped the one field that decides what the user sees, which is half of
    /// why a rejection could produce no affordance at all (QA #14).
    pub submit_error_code: Option<String>, // default = None
    /// `algoId` of the accepted order. Empty until a submit succeeds.
    pub submit_algo_id: String, // default = ""
    /// Leg leverage, as the raw string the form shows.
    /// 
    /// Added for Wave C1's final batch: when `OKTSArbLegContentHost` takes over
    /// `OKTPOContextDataDelegate`, it must source every context value from Rust
    /// instead of reading it back off native's child VCs. Every other member
    /// already had a state field; `lever` was the one gap
    /// (`OKTASPOContentVC.m:912` reads `buttonLineVC.leverValue` into
    /// `params.lever` on the pre-check sheet).
    /// 
    /// Not on the submit wire — the multi-order body carries no `lever`
    /// (`getCommitArbitrageParams` never sets it). Pre-check display only, so an
    /// empty value must stay empty rather than defaulting to `"1"`, which would
    /// assert a leverage the user never chose.
    pub left_lever: String, // default = ""
    pub right_lever: String, // default = ""
    /// Raw `OKTASPODirectionValue` the leg's direction control currently shows.
    /// 
    /// This is the SINGLE source for the leg's direction: [`Self::left_side`] and
    /// [`Self::left_pos_side`] are derived from it by
    /// [`ArbitragePlaceOrderActions::set_left_direction`], so side and posSide can
    /// never disagree with the identity the user picked. Before Wave C1 the native
    /// direction VC owned the identity and pushed side/posSide separately, which
    /// is exactly the shape that let them drift.
    /// 
    /// Empty until the direction control seeds it. Empty is NOT coerced to a
    /// default direction — an unset direction must read as unset, or the confirm
    /// sheet would show a direction the user never chose.
    pub left_direction: String, // default = ""
    /// See [`Self::left_direction`].
    pub right_direction: String, // default = ""
    /// FSM for the trade-config fetch. Enum-typed → no `#[uniffi(default)]`.
    pub load_trade_config_state: ActionResultState,
    /// Raw error text from the config fetch; `None` unless it failed.
    pub load_trade_config_error: Option<String>, // default = None
    /// Whether automatic price tracking is enabled (`userStrategyConfig.automaticTracking`).
    pub automatic_tracking: bool, // default = false
    /// Tracking interval in seconds (`userStrategyConfig.timeInterval`).
    pub time_interval: i32, // default = 0
    /// Whether tracking pauses at the threshold (`userStrategyConfig.pauseTracking`).
    pub pause_tracking: bool, // default = false
    /// Pause threshold, raw decimal string (`userStrategyConfig.pauseThreshold`).
    pub pause_threshold: String, // default = ""
    /// FSM for the trade-config write. Enum-typed → no `#[uniffi(default)]`.
    pub save_trade_config_state: ActionResultState,
    /// Raw error text from the config write; `None` unless it failed.
    pub save_trade_config_error: Option<String>, // default = None
    pub left_inst_type: String,
    pub left_inst_family: String,
    pub left_ticker_size: String,
    pub left_quote_symbol: String,
    pub right_inst_type: String,
    pub right_inst_family: String,
    pub right_ticker_size: String,
    pub right_quote_symbol: String,
    pub left_ticker_last: String,
    pub left_ticker_bid_px: String,
    pub left_ticker_ask_px: String,
    pub right_ticker_last: String,
    pub right_ticker_bid_px: String,
    pub right_ticker_ask_px: String,
    pub left_arb_info_side: String,
    pub right_arb_info_side: String,
    pub taker_range: i32,
    pub maker_range: i32,
    pub position_mode: String,
    pub account_level: String,
    pub is_multiple_account: bool,
    pub is_auto_borrow: bool,
    pub is_less_than_assembly_account: bool,
    pub is_equal_or_greater_multiple_account: bool,
    pub is_selected_same_amt: bool,
    pub is_selected_same_total: bool,
    pub is_left_select_reduce_only: bool,
    pub is_right_select_reduce_only: bool,
    /// Computed leg price as a decimal string. Empty when not yet
    /// computed or when the price-type branch returned nothing.
    pub left_computed_price: String,
    /// Computed leg price as a decimal string. Empty when not yet
    /// computed or when the price-type branch returned nothing.
    pub right_computed_price: String,
    /// Spread rate `(left - right) / right` as a decimal string. Empty
    /// when `spread_rate_valid` is false.
    pub spread_rate_value: String,
    pub spread_rate_valid: bool,
    /// Display twin of [`Self::spread_rate_value`].
    /// 
    /// The raw field is the unscaled ratio `(left - right) / right`; native shows
    /// a SIGNED PERCENT. Before this twin existed the iOS Rust arm passed the raw
    /// ratio straight into the shared price-settings label, so a spread native
    /// rendered as `+0.31%` appeared as `0.0030749…`.
    /// 
    /// Native leaf (`OKTArbStgyUtil.getDepthSpreadRateText`, m:31-42):
    /// `[[gap okt_divide:right].treatAsPercentage.prependPlusSign
    /// toLocalizedStringDownToMax:2]`, with `kOKTPOEmptyPlaceholder` ("--")
    /// when either input string is empty.
    /// 
    /// Three-way, matching native's three outcomes exactly:
    /// - `None` — the two legs' quote currencies differ. Native calls
    /// `updateSpreadRateWith:@""` (no text at all), NOT the "--" placeholder.
    /// - `Some(Placeholder)` — units match but an input is absent/unparseable →
    /// native's `kOKTPOEmptyPlaceholder`.
    /// - `Some(Percent{..})` — the real value.
    /// 
    /// Enum-typed → **no `#[uniffi(default)]`** (a bare one compiles under cargo
    /// then breaks bindgen on both platforms).
    pub spread_rate_display: Option<BotDisplayText>,
    pub left_close_position: bool,
    pub right_close_position: bool,
    pub left_reduce_only_visible: bool,
    pub right_reduce_only_visible: bool,
    pub left_spot_margin_market_buy: bool,
    pub right_spot_margin_market_buy: bool,
    pub left_refresh_dynamic_sz: bool,
    pub right_refresh_dynamic_sz: bool,
    pub left_reduce_only_select: Option<bool>,
    pub right_reduce_only_select: Option<bool>,
    pub left_price_filter_digit: i32,
    pub right_price_filter_digit: i32,
    pub is_official_arbitrage: Option<bool>,
    /// Base-converted ENTER price as a decimal string. Empty when
    /// unparseable; never coerced to zero (see `money_math.md`).
    /// One leg's `/max-available` rows, or `None` before the first response.
    /// 
    /// `None` is load-bearing: it is the pre-first-fetch state, in which native has
    /// no commit handler and every KV row renders its own `--` placeholder. A
    /// default-filled row would instead render five zeros, which reads as real data.
    pub left_avail: Option<ArbLegAvailRows>,
    pub right_avail: Option<ArbLegAvailRows>,
    /// One leg's `/leverage-info` rows — native's `marginInfoArr`.
    /// 
    /// An EMPTY vec is the legitimate "no leverage rows" state (not-logged-in, or a
    /// biz with no leverage), which is why this is a plain `Vec` and not an
    /// `Option`: `marginInfoByPosSide:` returns nil for both "never fetched" and
    /// "fetched, no rows", so native cannot tell them apart either and the lever
    /// control renders the same placeholder for both.
    pub left_margin_infos: Vec<ArbLegMarginInfo>,
    pub right_margin_infos: Vec<ArbLegMarginInfo>,
    pub left_enter_px_base: String,
    /// Base-converted ENTER price as a decimal string.
    pub right_enter_px_base: String,
}

/// Per-tab filtered row counts for the segment tab titles ("Fav(3)",
/// "Funding-rate(12)", "Spread(8)"). Computed over ALL data with search-text
/// filter applied (hidden-coin filter is a Swift post-filter and is NOT
/// reflected here — see Open Q B). Favourite count is 0 when `skip_favourites`
/// (Q6). Source: `OKTASearchFactory.refreshSegmentItem`.
#[derive(Debug, Clone, PartialEq)]
pub struct ArbitrageSearchSegmentCounts {
    pub favourite_count: u32,
    pub fee_rate_count: u32,
    pub spread_count: u32,
}

/// State for the arbitrage-search (pair-picker) flow.
/// 
/// Owns the three fetched lists (grouped by bucket, held once), the
/// view/filter state, the favourite membership, and the loading/error FSMs.
/// Derived rows + counts are recomputed after every mutation and stored so
/// observers see one consistent snapshot (same `modify_and_recompute` pattern
/// as `place_order.rs`).
#[derive(Debug, Clone, PartialEq)]
pub struct ArbitrageSearchState {
    pub funding_rate: FundingRateArbitrage,
    pub spread: SpreadArbitrage,
    pub favourites: ArbitrageFavouriteList,
    pub selected_tab: ArbitrageSearchTab,
    /// Normalized keyword (uppercase, `-`/`/` stripped, clamped 15). The raw
    /// box text lives in Swift.
    pub search_text: String,
    pub fee_rate_ccy_type: String,
    pub fee_rate_ct_type: String,
    pub spread_ccy_type: String,
    pub spread_ct_type: String,
    /// `OKTArbitrageFSFType`: `"futures_spot"` | `"futures_futures"`.
    pub spread_sa_type: String,
    pub sort_type: ArbitrageSearchSortType,
    pub sort_order: ArbitrageSearchSortOrder,
    /// = `iskArbitrageShowFavorList`; when true: no fav fetch, Favourite tab
    /// absent.
    pub skip_favourites: bool,
    /// Derived set of favourited `arbitrage_id`s, rebuilt from `favourites`
    /// after each fetch/re-fetch. Stored as `Vec` (uniffi has no Set).
    pub favourite_ids: Vec<String>,
    pub load_state: ActionResultState,
    pub load_error: Option<String>,
    pub set_favourite_state: ActionResultState,
    pub set_favourite_error: Option<String>,
    /// Rows for `selected_tab` after bucket filter → search filter → sort.
    pub current_rows: Vec<ArbitrageSearchRow>,
    /// Segment tab counts over all data with the search filter applied.
    pub segment_counts: ArbitrageSearchSegmentCounts,
    /// ccyType (margin) filter menu options for the FeeRate tab, one per bucket
    /// present in `funding_rate` (canonical order, INCLUDING linear/inverse —
    /// legacy `OKTAMenuFilter` parity). Swift prepends its own "All" item.
    pub fee_rate_ccy_types: Vec<ArbitrageCcyTypeOption>,
    /// ccyType (margin) filter menu options for the Spread tab, one per bucket
    /// present in `spread` (canonical order, INCLUDING linear/inverse).
    pub spread_ccy_types: Vec<ArbitrageCcyTypeOption>,
}

/// Resolved selection payload for a tapped row. `None` (from
/// `resolve_selection`) when a Favourite row's `arbitrage_id` is not found in
/// the currently-loaded FR/Spread lists (gap 4 not-in-list edge case, Q7) —
/// native then shows the "pair unavailable" path instead of navigating.
/// 
/// Maps 1:1 to the native `OKTArbSelection` (see type-design §7). Swift
/// constructs `OKTArbSelection` from this; the interactor does NOT build the
/// ObjC type itself.
#[derive(Debug, Clone, PartialEq)]
pub struct ArbitrageSelectionPayload {
    pub buy_inst_id: String,
    pub buy_inst_type: String,
    pub sell_inst_id: String,
    pub sell_inst_type: String,
    pub ccy: String,
    /// Bucket-derived favourite `ccyType`.
    pub ccy_type: String,
    /// Bucket-derived favourite `ctType`.
    pub ct_type: String,
    pub arbitrage_id: String,
    /// `"funding-rate"` / `"spread"`.
    pub group_type: String,
    /// Spread FSF sub-list type (e.g. `"futures_spot"` / `"futures_futures"`);
    /// `""` for funding-rate. This is the value the favourite POST requires —
    /// NOT `SpreadArbitrageItem.arb_type` (`"this_month-spot"`), which the
    /// server rejects (error 3902). See `ArbitrageSearchRow::Spread.sa_type`.
    pub arbitrage_type: String,
}

