#[derive(Debug, Clone, PartialEq)]
pub struct ContractDcaAddInvestmentState {
    pub algo_id: String,
    pub inst_id: String,
    pub amount: String,
    pub limit_price: String,
    /// BE TD §4: valid values {"limit"(default), "market"}
    pub ord_type: DcaOrderType,
    /// Minimum size from the active metadata authority (Rust on Android,
    /// caller-provided on iOS). Retained for compatibility; not used by the
    /// current minimum-margin formula.
    pub min_sz: String,
    /// Stop-loss price. For Long: limit must be >= sl_px.
    pub sl_px: String,
    /// Liquidation price. Checked as price floor/ceiling if sl_px is empty.
    pub liq_px: String,
    /// Exchange buy-price ceiling (from OKTLimitPriceDataSource).
    /// Long limit validation: limit must not exceed buy_lmt.
    pub buy_lmt: String,
    /// Exchange sell-price floor (from OKTLimitPriceDataSource).
    /// Short limit validation: limit must not fall below sell_lmt.
    pub sell_lmt: String,
    /// Trade direction — determines `side` for MaxAvailable params.
    pub direction: ContractDcaDirection,
    /// Strategy leverage supplied by native (e.g. "5").
    pub lever: String,
    /// Contract value (`ctVal`) from the active metadata authority.
    pub ct_val: String,
    /// Lot size (`lotSz`) from the active metadata authority. Blank/zero uses
    /// the existing price-only minimum-margin fallback.
    pub lot_sz: String,
    /// Investment currency from the active metadata authority (e.g. "USDT").
    pub invest_ccy: String,
    /// Trade mode: "cross" | "isolated" — from instrument context.
    pub td_mode: String,
    /// Position mode — required by OKX `max-available` for SWAP/futures.
    /// Pushed from iOS at sheet open (`OKTrade.sharedTrade.tradeSetting.posMode`).
    /// Empty defaults to "net_mode" at param-build time (the SWAP one-way default).
    /// 
    /// TODO(rust-owns-everything): once Rust grows a trade-settings use case
    /// (e.g. /priapi/v5/account/settings), fetch this directly and drop the
    /// iOS-side `set_pos_mode` action.
    pub pos_mode: String,
    pub latest_price: String,
    pub available_trade: String,
    pub available_balance: String,
    pub formatted_available_total: String,
    /// Minimum required margin (derived from the inline `(1 + 0.001 × lever)`
    /// formula in `OKTSIncreassPositionSheetVC.m:683`).
    pub min_amount: String,
    /// `latest_price` run through the instrument's charge convertor
    /// (index/mark → quote), UNROUNDED — native rounds via `price_precision`.
    /// Empty until the instrument resolves; native must not render it at
    /// precision 0 in that window (mirrors the `formatted_available_total`
    /// gating already used for `min_amount`).
    pub latest_price_quote: String,
    /// Display precision for `latest_price_quote` — same source
    /// (`ChargeCurrency.price_dig`) as the `price` role in
    /// `ContractDcaConvertors`. `0` is meaningless on its own; only valid
    /// paired with a non-empty `latest_price_quote`.
    pub price_precision: u8,
    /// Margin/investment display convertor — symbol + precision for
    /// `available_balance` / `available_trade` / `formatted_available_total`.
    /// `None` while the instrument is unresolved (Rule 18: never publish a
    /// defaulted, precision-0 convertor that would truncate a real amount).
    pub margin_convertor: Option<BotConvertor>,
    pub validation_error: ContractDcaValidationError,
    pub lifecycle: ContractDcaLifecycle,
    pub is_loading_max_available: bool,
    pub is_loading_balance: bool,
    pub is_pre_checking: bool,
    pub is_submitting: bool,
    pub last_check_diff_amt: String,
    pub last_submitted_algo_id: String,
    pub error_message: Option<String>,
    /// Quote currency from the same Android Rust-owned instrument snapshot as
    /// `ct_val` / `lot_sz` / `invest_ccy`. Appended for UniFFI record stability.
    pub price_ccy: String, // default = ""
}

