/// Bundled create-form snapshot for the safe Android/JNA submit entry.
/// 
/// Keep this as one UniFFI Record: the earlier 16-loose-argument version was
/// verified on device to mis-marshal stack-spilled RustBuffers on arm64. The
/// legacy loose action remains exported for source compatibility, while new
/// native callers must use this record-backed path.
#[derive(Debug, Clone, PartialEq)]
pub struct SignalBotPrepareOrderInput {
    pub signal_chan_id: String,
    pub source_type: SignalSourceType,
    pub inst_ids: Vec<String>,
    pub lever: String,
    pub total_amt: String,
    pub sub_ord_type: SubOrderType,
    /// Nullable exactly like native `SignalBotReq.ratio`: untouched market
    /// forms omit the key, while visiting the order-type screen may retain an
    /// empty or previous limit ratio even after switching order type.
    pub ratio: Option<String>,
    pub entry_dele_type: EntryDelegationType,
    pub entry_amt: Option<String>,
    pub entry_amt_ratio: Option<String>,
    pub tp_sl_type: Option<TpSlType>,
    pub tp_percentage: Option<String>,
    pub sl_percentage: Option<String>,
    pub allow_multiple_entry: bool,
    pub max_positions: Option<String>,
    pub td_mode: String,
    /// The user's confirm-before-order preference, mirrored into state for
    /// UI hints. Whether Rust re-validates is controlled by
    /// `native_prevalidated`, not by this preference.
    pub confirm_before_order: bool,
    /// `true`: Native has already run its preCheck + child-sheet validation
    /// and (when configured) its confirmation sheet, so Rust must preserve
    /// that decision and POST without applying a second, potentially stale
    /// rule set. `false`: Rust owns validation and exposes `ShowConfirm`
    /// when `confirm_before_order` is set.
    pub native_prevalidated: bool,
    /// Opaque IM attribution tag. Native preserves a non-null empty string;
    /// only `null` omits the key under `encodeDefaults=false`.
    pub tag: Option<String>,
}

