/// Public domain model for a single Simple Grid AI parameter set.
/// 
/// One entry per user-risk-mode (typically 3 entries from the wire:
/// "aggressive" / "moderate" / "conservative"). All money fields stay as
/// `String` across the UniFFI boundary (`Decimal` is not a UniFFI
/// primitive); call sites convert with `decimal::Decimal::from_str` when
/// arithmetic is required — see `docs/conventions/money_math.md`.
/// 
/// Native display labels (iOS / Android) are derived from
/// [`Self::user_risk_mode`] but are not the same string; the wire values
/// listed above are authoritative.
#[derive(Debug, Clone, PartialEq)]
pub struct SimpleGridAIParam {
    pub inst_id: String,
    /// Algo order type — typically "grid" for Simple Spot Grid.
    pub algo_ord_type: String,
    /// Discriminator: "aggressive" / "moderate" / "conservative".
    pub user_risk_mode: String,
    /// Backtest duration window — typically "7D" / "30D" / "180D".
    pub duration: String,
    /// Backtested annualized rate, e.g. "4.3476".
    pub annualized_rate: String,
    pub min_investment: String,
    /// Lower price bound.
    pub min_px: String,
    /// Upper price bound.
    pub max_px: String,
    pub grid_num: String,
    /// "1" = arithmetic, "2" = geometric.
    pub run_type: String,
    pub per_min_profit_rate: String,
    pub per_max_profit_rate: String,
    pub per_grid_profit_ratio: String,
    pub direction: String,
    pub lever: String,
    pub ccy: String,
    pub source_ccy: String,
    /// Backtest pnl history — flat list of `pnlRatio` values. Items the
    /// server returns without a `pnlRatio` field are filtered out at the
    /// DTO boundary so native callers never see empty placeholders.
    pub profit_history: Vec<String>,
}

