/// State for the Spot Grid edit parameters flow.
#[derive(Debug, Clone, PartialEq)]
pub struct SpotGridEditParametersState {
    /// Original lower price
    pub original_min_px: String,
    /// Original upper price
    pub original_max_px: String,
    /// Original grid quantity
    pub original_grid_num: String,
    /// Minimum grid quantity (from Strategy Config API)
    pub min_grid_num: u32,
    /// Maximum grid quantity (from Strategy Config API - static limit)
    pub config_max_grid_num: u32,
    /// Effective max grid quantity (min of config_max and dynamic max from grid-num-range API)
    pub effective_max_grid_num: u32,
    /// Min profit rate per grid (e.g., "0.00188...")
    pub profit_rate_min: Option<String>,
    /// Max profit rate per grid (e.g., "0.00411...")
    pub profit_rate_max: Option<String>,
    /// Profit currency
    pub profit_ccy: Option<String>,
    /// Required topup amount
    pub required_topup_amount: Option<String>,
    /// Validation error message
    pub validation_error: Option<String>,
    /// Loading config flag
    pub is_loading_config: bool,
    /// Loading estimates flag
    pub is_loading_estimates: bool,
    /// Submitting flag
    pub is_submitting: bool,
    /// Submit success flag
    pub submit_success: Option<bool>,
    /// Submit error message
    pub submit_error_message: Option<String>,
    /// Submit business sub-error code (`sCode`) on a soft-fail submit
    /// (`success == false`), forwarded verbatim from the wire
    /// (`EditSubmitResult::error_code`). Additive/forward-compatible: native
    /// hosts that need to branch on actionable business codes (e.g. the spot
    /// grid edit-params insufficient-balance / insufficient-topup re-edit
    /// dialogs keyed on `55123` / `55124`) read this instead of string-matching
    /// `submit_error_message`. `None` on success or transport-level errors
    /// (those surface via `error`).
    pub submit_error_code: Option<String>,
    /// General error
    pub error: Option<String>,
    pub presentation: SpotGridEditParametersPresentation,
    pub operation_generation: u64,
    pub cancelled: bool,
    pub base_sz: String,
    pub quote_sz: String,
    pub source_ccy_sz: String,
    pub source_ccy: String,
    pub trade_quote_ccy: String,
    pub holding_distribution: Vec<SpotGridHoldingDistribution>,
    /// Dynamic bound computed from the original range during config loading.
    pub config_dynamic_max_grid_num: Option<u32>, // default = None
    /// Dynamic bound for the latest edited input. This wins over the original-range bound.
    pub estimate_dynamic_max_grid_num: Option<u32>, // default = None
    /// Raw minimum profit amount per grid. Kept separate from its display operand.
    pub per_min_profit_amt: Option<String>, // default = None
    /// Raw maximum profit amount per grid. Kept separate from its display operand.
    pub per_max_profit_amt: Option<String>, // default = None
    /// Raw max-available quote balance. `None` means unavailable, never zero.
    pub available_quote_amount: Option<String>, // default = None
    /// Amount operands captured from the estimate for the unedited input. They
    /// must survive later edited estimates for the confirmation's Before row.
    pub original_per_min_profit_amt: Option<String>, // default = None
    pub original_per_max_profit_amt: Option<String>, // default = None
    /// Independent loading phase for the frozen confirmation allocation.
    pub is_loading_confirmation_allocation: bool, // default = false
    /// Distinguishes a submit transport failure from unrelated config/form
    /// errors when deriving confirmation-only legacy feedback.
    pub submit_attempted: bool, // default = false
}

