/// Input parameters for calculate_estimates and submit actions.
#[derive(Debug, Clone, PartialEq)]
pub struct SpotGridPlaceOrderInput {
    /// Run type ("1" = arithmetic, "2" = geometric).
    pub run_type: String,
    pub min_px: String,
    pub max_px: String,
    pub grid_num: String,
    /// Quote currency amount (e.g., USDT). Can be "0" if only investing base.
    pub quote_sz: String,
    /// Base currency amount (e.g., BTC). Can be "0" if only investing quote.
    pub base_sz: String,
    /// Invest type code — forwarded verbatim to the wire `investType`
    /// field (Kotlin supplies "AI_GRID"/"MANUAL_GRID" → the backend reads
    /// these as "1"/"2"). Empty string defaults to "2" via
    /// `normalize_invest_type`; any other value passes through unchanged.
    /// Investment mode (quote/base/dual) is conveyed to the backend
    /// through which of `quote_sz` / `base_sz` is non-zero, NOT this field.
    pub invest_type: String,
    /// Profit sharing ratio (e.g., "10" for 10%).
    pub profit_sharing_ratio: String,
    /// Reserve funds for stop-loss (optional).
    pub reserve_funds: Option<bool>,
    /// Whether profit auto reinvest is applicable, and its enabled flag.
    /// `None` → the wire `profitAutoReinvestParam` is omitted entirely
    /// (legacy parity); `Some(b)` → emits `{ enabled: b }`.
    pub profit_auto_reinvest_enabled: Option<bool>,
    /// Source currency (legacy `GridReq.sourceCcy`). Blank → omitted.
    pub source_ccy: Option<String>,
    /// Source-currency investment size (legacy `GridReq.sourceCcySz`).
    /// Blank → omitted.
    pub source_ccy_sz: Option<String>,
    /// Copy/NMP attribution source (legacy `GridReq.systemSource`).
    /// Blank → omitted.
    pub system_source: Option<String>,
    /// NMP underlying identifier (legacy `GridReq.nmpUnderlyingId`).
    /// Blank → omitted.
    pub nmp_underlying_id: Option<String>,
    /// Loss-insurance voucher identifier (legacy `GridReq.voucherId`).
    /// Blank → omitted.
    pub voucher_id: Option<String>,
    /// Loss-insurance voucher batch number (legacy `GridReq.batchNo`).
    /// Legacy's voucher use-case sets `voucherId` and `batchNo` as a pair
    /// and nulls both when the voucher id is empty. Blank → omitted.
    pub batch_no: Option<String>,
    /// Min-follow-invest amount (lead-trader profit-sharing bots). Forwarded
    /// to the wire `minFollowInvestAmount`, emitted only when > 0
    /// (COMMIT:22-25). New field → carries a `#[uniffi(default)]` so the
    /// generated native init stays source-compatible.
    pub min_follow_invest_amount: Option<String>, // default = None
    /// Smart-earn params JSON blob (legacy `GridReq.earnParam`). Empty /
    /// unparseable → omitted.
    pub earn_param_json: String,
    /// Trigger strategy params JSON (raw string).
    pub sign_params_json: String,
    /// Trailing up config JSON (raw string).
    pub trailing_up_config_json: String,
    /// Trailing down config JSON (raw string).
    pub trailing_down_config_json: String,
    /// TP/SL trigger params JSON (raw string).
    pub tpsl_trigger_param_json: String,
    /// CR-7: opaque IM attribution tag from the iOS deeplink. Blank / None →
    /// the wire `tag` key is omitted (empty ≡ absent).
    pub tag: Option<String>,
}

/// State for the Spot Grid Place Order flow.
#[derive(Debug, Clone, PartialEq)]
pub struct SpotGridPlaceOrderState {
    /// Trading pair, e.g. "BTC-USDT".
    pub inst_id: String,
    /// Selected quote currency for the pair (drives balance ccy + wire
    /// `tradeQuoteCcy`). Promoted from the ctor arg so the ViewState carries
    /// it; seeded / updated by `set_inst_context`.
    pub trade_quote_ccy: String,
    /// Canonical raw user intent. Every user edit mutates this record inside
    /// the interactor and advances `draft.revision`; native never assembles a
    /// place-order payload from view contents.
    pub draft: SpotGridCreateDraft,
    /// Passive-rendering projection for the current draft revision. Precision,
    /// rounding, unit selection, validation and reserve math are final here.
    pub create_presentation: SpotGridCreatePresentation,
    /// Field errors stay hidden on a freshly opened/seeded form. Any typed
    /// create edit or an invalid prepare attempt reveals the durable
    /// validation projection without changing submit eligibility.
    pub create_validation_revealed: bool,
    /// Immutable confirmation prepared from one normalized draft revision.
    /// Editing the draft or changing instrument context invalidates it.
    pub create_confirmation: Option<SpotGridCreateConfirmation>,
    pub confirmation_action_state: SpotGridConfirmationActionState,
    pub price_range_warning: Option<SpotGridPriceRangeWarningPresentation>,
    pub prepare_blocked: Option<SpotGridCreateBlockedPresentation>,
    /// Latest market price used by Rust reserve/investment projections. This is
    /// raw and locale-neutral; it is never copied into a submit payload.
    pub market_price: String,
    pub market_price_tone: SpotGridTickerTone,
    pub strategy_selector: SpotGridStrategySelectorPresentation,
    /// Session/UI preference acknowledgement for the one-time reserve warning.
    pub reserve_warning_acknowledged: bool,
    pub show_onshore_spot_terms: bool,
    pub create_platform_flags: SpotGridCreatePlatformFlags,
    pub create_recommendation_context: Option<SpotGridCreateRecommendationContext>,
    pub start_rsi_trigger_count: Option<String>,
    pub stop_rsi_trigger_count: Option<String>,
    pub is_loading_start_rsi_trigger: bool,
    pub is_loading_stop_rsi_trigger: bool,
    pub start_rsi_trigger_error: Option<String>,
    pub stop_rsi_trigger_error: Option<String>,
    /// Rust-owned projection of the first eligibility response item. Hidden
    /// while absent, ineligible, failed, or carrying an unsupported status.
    pub loss_insurance: SpotGridLossInsurancePresentation,
    pub is_loading_loss_insurance: bool,
    pub loss_insurance_error: Option<String>,
    /// Minimum grid quantity (from StrategyConfig)
    pub min_grid_num: u32,
    /// Effective maximum grid quantity: min(config_max, dynamic_max)
    pub effective_max_grid_num: u32,
    /// Last dynamic max from the grid-num-range API (price-range narrowing).
    /// Kept so a late-arriving strategy config RECOMPUTES the min instead of
    /// clobbering the narrowing (QA F21 race: config after num-range showed
    /// the raw config max). Legacy computes the min at display time and
    /// cannot race.
    pub dynamic_max_grid_num: Option<u32>,
    /// Max grid quantity from StrategyConfig
    pub max_grid_num: u32,
    /// Strategy config (typed UniFFI Record). `Some(_)` once
    /// `fetch_strategy_config` succeeds.
    pub strategy_config: Option<StrategyConfigInfo>,
    /// Auto Earn configuration summary (for UI display).
    pub auto_earn_summary: Vec<String>,
    /// Auto Staking configuration summary (for UI display).
    pub auto_staking_summary: Vec<String>,
    pub max_available_quote: Option<String>,
    pub max_available_base: Option<String>,
    /// Source-ccy (crypto→USDT) available — the quote-side cap of the
    /// native-seeded source pair (legacy `updateSourceCcyCommitOrderHandler`
    /// reads `displayAvail.quoteMax` off the source-inst handler). `None`
    /// for USDT/USDC-quoted pairs, where the source mode is not offered.
    pub max_available_source: Option<String>,
    /// Raw available balance for every Trade-With option, keyed by currency.
    pub trade_with_balances: HashMap<String, String>,
    /// Source-pair instrument id (`QUOTE-USDT`), seeded by native via
    /// `set_inst_context` — see `SpotGridInstContextInput::source_inst_id`.
    pub source_inst_id: Option<String>,
    pub min_quote_sz: Option<String>,
    pub min_base_sz: Option<String>,
    /// Minimum source-ccy (crypto→USDT) order size (raw; native rounds UP).
    pub min_source_sz: Option<String>,
    /// Extra quote required to reserve funds on a trailing-down grid — feeds
    /// the actual-investment (#23) row (raw; native composes the display).
    pub additional_quote_investment: Option<String>,
    /// Extra base leg feeding the max-bot-usage (#24) row (raw; native
    /// multiplies by `ticker.last` for the display value).
    pub additional_base_investment: Option<String>,
    /// Loading flag for the additional-investment fetch.
    pub is_loading_additional_investment: bool,
    /// Default trailing stop / bound prices for the current price range + grid
    /// count. `None` whenever the inputs are incomplete or the fetch failed —
    /// legacy clears the trailing rows in BOTH cases (`trailingPxLd.postValue(null)`
    /// and the `getTrailingPxUseCase` error branch calling `syncTrailingResp()`).
    pub trailing_px: Option<TrailingPx>,
    /// Explicit preview lifecycle. `trailing_px == None` alone cannot tell an
    /// in-flight request from a completed response with an omitted bound.
    pub trailing_preview_status: SpotGridTrailingPreviewStatus,
    /// A disabled -> enabled transition may consume one delayed suggestion,
    /// provided the user has not edited or cleared that direction meanwhile.
    pub trailing_up_prefill_pending: bool,
    pub trailing_down_prefill_pending: bool,
    /// Copy/NMP attribution source (`systemSource` on the wire).
    pub system_source: Option<String>,
    /// NMP underlying identifier (`nmpUnderlyingId` on the wire).
    pub nmp_underlying_id: Option<String>,
    /// Loss-insurance voucher id (`voucherId` on the wire; pairs with batch).
    pub voucher_id: Option<String>,
    /// Loss-insurance voucher batch number (`batchNo` on the wire).
    pub batch_no: Option<String>,
    /// Derived: a loss-insurance voucher is present → native renders the
    /// loss-insurance chip (#33).
    pub show_loss_insurance: bool,
    /// Min profit rate per grid (e.g., "0.00188" = 0.188%)
    pub profit_rate_min: Option<String>,
    /// Max profit rate per grid (e.g., "0.00411" = 0.411%)
    pub profit_rate_max: Option<String>,
    /// Per-min profit amount (raw string from API).
    pub per_min_profit_amt: Option<String>,
    /// Per-max profit amount (raw string from API).
    pub per_max_profit_amt: Option<String>,
    /// Profit currency (raw string from API).
    pub profit_ccy: Option<String>,
    /// Max grid number from profit rate response (raw string).
    pub profit_max_grid_num: Option<String>,
    /// AI recommended strategy name
    pub ai_strategy_name: Option<String>,
    /// AI recommended min price
    pub ai_min_px: Option<String>,
    /// AI recommended max price
    pub ai_max_px: Option<String>,
    /// AI recommended grid num
    pub ai_grid_num: Option<String>,
    /// AI recommendation list (for strategy selection)
    pub ai_recommendations: Vec<SpotGridAiRecommendationItem>,
    pub ai_chat_selected_index: u32,
    pub ai_chat_amounts: HashMap<String, String>,
    pub ai_chat_translation: Option<String>,
    pub ai_chat_translation_loading: bool,
    pub ai_chat_translation_error: Option<String>,
    pub is_loading_ai_recommendation: bool,
    pub ai_recommendation_error: Option<String>,
    /// Structured (non-localized) validation error. Native switches on the
    /// variant; localization is native-owned (T5/T2.8).
    pub validation_error: Option<SpotGridValidationError>,
    pub is_loading_config: bool,
    pub is_loading_balance: bool,
    pub is_loading_min_investment: bool,
    pub is_loading_estimates: bool,
    pub is_loading_grid_num_range: bool,
    pub is_submitting: bool,
    /// Whether the user is a lead trader.
    pub is_lead_trader: bool,
    /// Whether profit sharing is enabled for this bot.
    pub profit_sharing_enabled: bool,
    /// Available profit sharing ratios (raw string values).
    pub profit_sharing_range: Vec<String>,
    /// Default profit sharing ratio from config.
    pub default_profit_sharing_ratio: Option<String>,
    /// Whether profit auto reinvest is editable.
    pub profit_auto_reinvest_editable: bool,
    /// Whether profit auto reinvest is enabled (user-owned once toggled).
    pub profit_auto_reinvest_enabled: bool,
    /// Profit auto reinvest start time (if any).
    pub profit_auto_reinvest_start_time: Option<String>,
    /// Set once the user toggles the reinvest switch; guards a late precheck
    /// frame from stomping the user's choice (T2.5, v1 defect #17).
    pub reinvest_user_dirty: bool,
    /// Whether investment exceeds available balance.
    pub over_max_avail: bool,
    /// Whether submit is enabled.
    pub can_submit: bool,
    pub submit_success: Option<bool>,
    pub algo_id: Option<String>,
    pub submit_error: Option<String>,
    /// Actionable business code from a submit failure. `"-1"` = transport /
    /// not-actionable. Reset on every attempt + on success so the bridge
    /// re-toasts identical consecutive failures (rising-edge dedup, T2.8).
    pub submit_error_code: Option<String>,
    /// Frozen trigger semantic for the terminal submit result. Native uses it
    /// only to route the existing TradingView success/failure surfaces.
    pub submit_was_trading_view: bool,
    pub last_algo_id: Option<String>,
    /// Fatal route-identity failure only. Child config, balance, AI, estimate, and
    /// confirmation-support requests keep their own local/degraded channels and never write here.
    pub error: Option<String>,
    pub status_message: Option<String>,
}

